  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Sports, Teamwork and Sportsmanship$j$, $j${"readings": [{"title": "1 Corinthians 9 (King James Version)", "url": "/portal/bible/1Corinthians/9"}], "body": "Sports teach skills that last a lifetime. In a team sport such as basketball, volleyball, soccer or football, players work together toward a shared goal. In an individual or dual sport such as track, swimming, tennis or golf, a player competes against a standard or an opponent. Both kinds build fitness, discipline, courage and friendship.\n\nEvery sport has basic skills, such as running, jumping, throwing, catching, striking, dribbling and passing, that are built by practice. Learn the rules, the positions and the safe way to play. Good coaching, good equipment and a proper warm up lower the risk of injury. The apostle Paul used the picture of a race in First Corinthians 9:24 and 25: Know ye not that they which run in a race run all, but one receiveth the prize? So run, that ye may obtain. And every man that striveth for the mastery is temperate in all things.\n\nSportsmanship means playing fairly and treating others with respect, whether you win or lose. A good sport follows the rules, respects officials and coaches, encourages teammates, shakes hands with opponents, wins without bragging and loses without excuses. A poor sport cheats, argues, taunts and blames others. Teamwork means doing your part, communicating, supporting teammates and putting the team before personal glory. Leaders in sports set an example of character. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men.\n\nRemember that sports are for growth and joy. Pressure to win at any cost, to play through injury or to use drugs to gain an edge is wrong. Keep school and faith first, and enjoy the game.\n\nYour task: (1) Compare a team sport and an individual sport and tell what skills each builds. (2) List five behaviors of a good sport. (3) Describe a time you showed good teamwork, or how you could.\n\nFlorida standards: PE.912.M.1, PE.912.R.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.M.1, PE.912.R.5", "script": "Welcome back. Listen, the field and the court are classrooms. They teach what no textbook can.\n\nIn a team sport like basketball, volleyball or soccer, players work together toward a shared goal. In an individual sport like track, swimming, tennis or golf, you compete against a standard or an opponent. Both build fitness, discipline, courage and friendship.\n\nNow watch this. Every sport builds on basic skills, like running, jumping, throwing, catching, striking and passing. Learn the rules and the safe way to play. Good coaching, proper equipment and a warm up lower your risk of injury.\n\nPaul used a race to teach us in First Corinthians 9:24. Know ye not that they which run in a race run all, but one receiveth the prize? So run, that ye may obtain. And every man that striveth for the mastery is temperate in all things.\n\nLook at sportsmanship. A good sport follows the rules, respects officials and coaches, encourages teammates, shakes hands with opponents, wins without bragging and loses without excuses. Teamwork means doing your part, communicating and putting the team before personal glory.\n\nColossians 3:23 says, whatsoever ye do, do it heartily, as to the Lord. Never cheat, never play through a serious injury, and never use drugs to gain an edge.\n\nYour task is to compare team and individual sports, list five good sport behaviors and describe your teamwork. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Sports, Teamwork and Sportsmanship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Lifetime Activities$j$, $j${"readings": [{"title": "Ecclesiastes 9 (King James Version)", "url": "/portal/bible/Ecclesiastes/9"}], "body": "Lifetime activities are activities a person can enjoy at many ages and with few or no teammates. Walking, hiking, jogging, swimming, cycling, dancing, yoga, tennis, golf, bowling, pickleball, martial arts for sport and fitness, rowing, kayaking, and gardening are examples. Many students play team sports in school, but after graduation fewer teams are available, so learning lifetime activities now helps keep a person active for decades.\n\nChoose activities by considering your interests, your health, the cost, the equipment and the place. South Florida offers many options all year: beaches, pools, parks, trails, tennis courts, golf courses, fishing, boating and community centers. Always follow safety rules. Wear a helmet when cycling, learn to swim and swim with a buddy or where a lifeguard is on duty, use sunscreen, wear a life jacket on the water, and watch for lightning. Florida has frequent thunderstorms, so go indoors at the first sound of thunder.\n\nSome activities are available through the church, community and family. Walking groups, church league sports, youth outreach events, family hikes and service projects can mix fitness with fellowship. Ecclesiastes 9:10 says, Whatsoever thy hand findeth to do, do it with thy might.\n\nTrying new activities keeps exercise fresh. Learn the skills, start slowly, and set goals. Invite a friend or family member. Count active time for chores and play, too. A person who has several favorite activities can stay fit in any season, in any place and at any age.\n\nYour task: (1) List five lifetime activities and explain why each can be done for many years. (2) Choose one new activity to try and list the safety steps you will follow. (3) Plan a family or church activity that includes physical activity.\n\nFlorida standards: PE.912.L.3, PE.912.M.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.L.3, PE.912.M.1", "script": "Welcome back. Listen, the day will come when you are no longer on a school team. What will you do then? Learn lifetime activities now.\n\nLifetime activities are activities you can enjoy at many ages with few or no teammates. Walking, hiking, jogging, swimming, cycling, dancing, yoga, tennis, golf, bowling, pickleball, kayaking and gardening are examples. After graduation there are fewer teams, so building these skills now helps you stay active for decades.\n\nNow watch this. Choose activities by your interests, your health, the cost, the equipment and the place. South Florida gives us beaches, pools, parks, trails, courts, golf courses and community centers all year.\n\nFollow safety rules. Wear a helmet when you cycle. Learn to swim, and swim with a buddy or where a lifeguard is on duty. Use sunscreen. Wear a life jacket on the water. And in Florida thunderstorms, go indoors at the first sound of thunder.\n\nLook at fellowship. Walking groups, church league sports, family hikes and service projects mix fitness with fellowship. Ecclesiastes 9:10 says, Whatsoever thy hand findeth to do, do it with thy might.\n\nTry new activities to keep exercise fresh. Invite a friend or a family member.\n\nYour task is to list five lifetime activities, choose one to try with safety steps, and plan a family or church activity. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Lifetime Activities$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Designing Your Personal Fitness Plan$j$, $j${"readings": [{"title": "Proverbs 16 (King James Version)", "url": "/portal/bible/Proverbs/16"}], "body": "A personal fitness plan puts everything you have learned to work. Proverbs 16:9 says, A man's heart deviseth his way: but the LORD directeth his steps. Plan well, and then trust God with the steps.\n\nFollow these steps. First, review your assessment results, your health, your interests and your schedule. Second, write two or three SMART goals, such as improving a timed one mile walk or run, completing a set number of push ups, or increasing flexibility on the sit and reach. Third, design the weekly program using the FITT principle. A good week for a teen might include aerobic activity on most days to reach 60 minutes daily, muscle strengthening on at least 3 days, bone strengthening activities such as jumping or running on at least 3 days, and flexibility work on most days. Fourth, include a warm up and a cool down in every session. Fifth, add a plan for nutrition, hydration, sleep and stress. Sixth, plan for safety, including adult approval, the heat, and what to do if you are injured. Seventh, plan for obstacles, such as bad weather, a busy schedule or low motivation, and decide on solutions.\n\nTrack your progress in your activity log. Retest every 4 to 6 weeks and adjust the plan. If you meet a goal, set a new one. If you miss one, ask why and adjust. Accountability helps, so share your plan with a parent, a friend or a coach. Reward yourself in healthy ways.\n\nYour plan should be balanced and realistic, not extreme. A plan that you will actually follow is better than a perfect plan you will quit.\n\nYour task: (1) Write two SMART goals. (2) Design a weekly schedule using FITT that includes aerobic, strength and flexibility work. (3) Identify three obstacles and your solutions.\n\nFlorida standards: PE.912.L.3, PE.912.C.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.L.3, PE.912.C.2", "script": "Welcome back. Listen, today you build your own plan. Proverbs 16:9 says, A man's heart deviseth his way: but the LORD directeth his steps. Plan well, then trust God with the steps.\n\nHere are the steps. First, review your assessments, your health, your interests and your schedule. Second, write two or three SMART goals. Third, design your week with the FITT principle. A good teen week includes aerobic activity on most days to reach 60 minutes daily, muscle strengthening on at least three days, bone strengthening like jumping or running on at least three days, and flexibility work on most days.\n\nNow watch this. Fourth, include a warm up and cool down in every session. Fifth, plan your nutrition, hydration, sleep and stress. Sixth, plan for safety. Get adult approval, plan for the heat, and know what to do if you are injured. Seventh, plan for obstacles, like bad weather, a busy schedule or low motivation, and decide on solutions ahead of time.\n\nLook at tracking. Use your activity log. Retest every four to six weeks and adjust. Meet a goal, set a new one. Miss a goal, ask why and adjust. Share your plan with a parent, a friend or a coach for accountability.\n\nA plan you will actually follow is better than a perfect plan you will quit.\n\nYour task is to write two SMART goals, design a weekly schedule and identify three obstacles with solutions. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Designing Your Personal Fitness Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Fitness Over a Lifetime and Service$j$, $j${"readings": [{"title": "1 Timothy 4 (King James Version)", "url": "/portal/bible/1Timothy/4"}], "body": "Fitness needs change over a lifetime, but the need to be active never ends. In the teen years the body is building bone and muscle quickly, and most people reach their peak bone mass by the late twenties, so activity now builds a strong skeleton for life. Adults are advised to get at least 150 minutes of moderate activity each week plus muscle strengthening on 2 or more days. Older adults gain from walking, balance training and strength work, which help prevent falls and keep independence. People with injuries, disabilities or health conditions can still be active in ways their doctors approve. Isaiah 46:4 says, Even to your old age I am he; and even to hoar hairs will I carry you.\n\nBalance is wise. First Timothy 4:8 says, For bodily exercise profiteth little: but godliness is profitable unto all things, having promise of the life that now is, and of that which is to come. This verse does not say that exercise is bad. It says that physical training is useful, and that godliness matters even more. Caring for the body is one way to serve God, but we must never worship the body or let fitness become a source of pride or an obsession. Keep your life in order: faith, family, school, rest, service and recreation.\n\nFitness can serve others. A strong, healthy person can carry groceries for a neighbor, volunteer at a community event, coach children, join a church outreach, run a charity walk, or help at a food bank. Many ministries and neighborhoods need strong hands. Teach younger children how to be active and set the example of a healthy life. Healthy habits you form now can help your future family and community.\n\nYour task: (1) Explain how fitness needs change through life and why activity matters at every age. (2) Explain what First Timothy 4:8 teaches about balance. (3) Plan one way to use your fitness to serve others.\n\nFlorida standards: PE.912.L.3, PE.912.R.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "PE.912.L.3, PE.912.R.5", "script": "Welcome back. Listen, this is our last lesson, and I want to leave you with the big picture.\n\nFitness needs change over a lifetime, but the need to be active never ends. In the teen years your body is building bone and muscle quickly, and most people reach peak bone mass by the late twenties. Activity now builds a strong skeleton for life. Adults are advised to get at least 150 minutes of moderate activity each week, plus muscle strengthening on two or more days. Older adults benefit from walking, balance and strength work, which help prevent falls and keep independence. People with injuries or health conditions can still be active in ways their doctors approve. Isaiah 46:4 says, Even to your old age I am he; and even to hoar hairs will I carry you.\n\nNow watch this. First Timothy 4:8 says, For bodily exercise profiteth little: but godliness is profitable unto all things, having promise of the life that now is, and of that which is to come. Exercise is useful. Godliness matters even more. Care for your body as an act of service, but never worship the body or let fitness become pride or an obsession.\n\nLook at service. A strong, healthy person can carry groceries for a neighbor, coach children, volunteer at a community event, join a church outreach or help at a food bank. Set an example of a healthy life.\n\nYour task is to explain how fitness needs change, explain First Timothy 4:8 and plan a way to serve others. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Fitness Over a Lifetime and Service$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Lifetime Fitness$j$, $j${"prompt": "Write a report of at least 250 words on lifetime fitness. Use complete sentences and label each part. First Timothy 4:8 says, For bodily exercise profiteth little: but godliness is profitable unto all things, having promise of the life that now is, and of that which is to come.\n\nPart 1: Compare a team sport and an individual sport and describe five behaviors of good sportsmanship.\nPart 2: List five lifetime activities, choose one you will try and describe the safety steps you will follow.\nPart 3: Write two SMART goals and a one week schedule that follows the FITT principle.\nPart 4: Describe three obstacles to staying active and your solutions.\nPart 5: Explain how fitness needs change through life, what First Timothy 4:8 teaches about balance, and one way you will use your fitness to serve others.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 25 points. Part 4: 15 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Lifetime Fitness$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Fit for Life and for Service$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells which lifetime activity you will keep doing after high school and why, (2) explains how sportsmanship shows character, (3) describes one way you will serve others with a healthy body, and (4) connects your answer to First Timothy 4:8 or First Corinthians 9:24 and 25. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a person stay balanced so that fitness does not become pride or an obsession? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Fit for Life and for Service$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Sports, Teamwork and Sportsmanship$j$, $j${"questions": [{"q": "Which is a team sport?", "options": ["Basketball", "Golf alone", "Solo swimming practice", "Solo running"]}, {"q": "A good sport:", "options": ["Taunts opponents", "Follows the rules and respects opponents", "Cheats to win", "Blames officials"]}, {"q": "Teamwork means:", "options": ["Quitting when losing", "Doing your part and supporting teammates", "Ignoring the coach", "Playing only for personal glory"]}, {"q": "First Corinthians 9:24 uses the picture of a:", "options": ["Race", "Harvest", "Building", "Ship"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Sports, Teamwork and Sportsmanship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,0}'::int[], array[$j$Basketball players work together toward a shared goal.$j$,$j$Sportsmanship means fair play and respect.$j$,$j$A team succeeds when each person contributes.$j$,$j$Paul compared the Christian life to running a race.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Sports, Teamwork and Sportsmanship$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Lifetime Activities$j$, $j${"questions": [{"q": "A lifetime activity is one that:", "options": ["Is only a school sport", "Can be enjoyed at many ages with few teammates", "Requires a full team", "Can be done only in youth"]}, {"q": "A Florida thunderstorm safety rule is to:", "options": ["Keep swimming", "Go indoors at the first sound of thunder", "Finish the game outdoors", "Stand under a tree"]}, {"q": "When cycling, you should wear a:", "options": ["Headphones only", "Sandals", "Nothing", "Helmet"]}, {"q": "Which is a good way to stay active after leaving school teams?", "options": ["Wait until age 50", "Only watch sports", "Learn lifetime activities now", "Quit exercise"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Lifetime Activities$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,2}'::int[], array[$j$Walking, swimming and cycling are examples.$j$,$j$Lightning can strike before rain arrives.$j$,$j$A helmet protects the head.$j$,$j$Lifetime skills keep a person active for decades.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Lifetime Activities$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Designing Your Personal Fitness Plan$j$, $j${"questions": [{"q": "A good first step in making a fitness plan is to:", "options": ["Choose the hardest workout", "Skip safety", "Copy a friend's plan exactly", "Review assessment results, health, interests and schedule"]}, {"q": "A balanced week for a teen includes:", "options": ["No rest", "Only stretching", "Aerobic, strength, bone strengthening and flexibility work", "Only one hard workout"]}, {"q": "Retesting every 4 to 6 weeks helps you:", "options": ["Quit", "Ignore results", "See progress and adjust the plan", "Avoid goals"]}, {"q": "A plan for obstacles might include:", "options": ["Skipping sleep", "Giving up when it rains", "Ignoring pain", "An indoor workout for rainy days"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Designing Your Personal Fitness Plan$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,2,3}'::int[], array[$j$A plan should fit the person.$j$,$j$A variety of activity meets the guidelines.$j$,$j$Regular testing shows what is working.$j$,$j$Planning ahead keeps you on track.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Designing Your Personal Fitness Plan$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Fitness Over a Lifetime and Service$j$, $j${"questions": [{"q": "Adults are advised to get at least how many minutes of moderate activity weekly?", "options": ["150", "15", "30", "600"]}, {"q": "First Timothy 4:8 teaches that:", "options": ["Rest is wrong", "Exercise is useful, but godliness is profitable for all things", "Faith does not matter", "Exercise is evil"]}, {"q": "Activity in the teen years helps build:", "options": ["Poor posture", "Weak bones", "Strong bones for life", "Less muscle"]}, {"q": "One way to use fitness to serve others is to:", "options": ["Avoid people", "Volunteer at a community event or help a neighbor", "Skip church", "Boast about workouts"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Fitness Over a Lifetime and Service$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,1}'::int[], array[$j$The guideline is at least 150 minutes a week.$j$,$j$The verse calls for balance with godliness first.$j$,$j$Most people reach peak bone mass by the late twenties.$j$,$j$Fitness can be a tool for service.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Fitness Over a Lifetime and Service$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Lifetime Fitness$j$, $j${"questions": [{"q": "Basketball is an example of a:", "options": ["Solo hobby", "Board game", "Team sport", "Water sport only"]}, {"q": "Good sportsmanship includes:", "options": ["Cheating", "Taunting", "Blaming teammates", "Respecting opponents and officials"]}, {"q": "Which is a lifetime activity?", "options": ["Walking", "Quitting", "Sleeping all day", "Waiting"]}, {"q": "The safest response to thunder in Florida is to:", "options": ["Ignore it", "Stand under a tree", "Go indoors", "Keep swimming"]}, {"q": "A personal fitness plan should include:", "options": ["Goals, a schedule, safety and tracking", "Only one workout", "Only copying others", "No rest"]}, {"q": "The teen guideline for daily activity is at least:", "options": ["60 minutes", "5 minutes", "3 hours", "10 minutes"]}, {"q": "Most people reach peak bone mass by about the:", "options": ["Age 8", "Age 60", "Age 40", "Late twenties"]}, {"q": "First Timothy 4:8 says that godliness is:", "options": ["Profitable in nothing", "Only for adults", "Profitable unto all things", "Unimportant"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Lifetime Fitness$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,0,2,0,0,3,2}'::int[], array[$j$Players work together toward a common goal.$j$,$j$Fair play and respect define sportsmanship.$j$,$j$Walking can be done at nearly every age.$j$,$j$Lightning is dangerous.$j$,$j$A good plan is complete and realistic.$j$,$j$Sixty minutes a day is the national guideline.$j$,$j$Activity in the teen years builds strong bones.$j$,$j$Exercise is useful, but godliness matters more.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Lifetime Fitness$j$ on conflict (item_id) do nothing;
